mapper.select:
SELECT num, member_num, type, category, content, status, created_date
FROM (
    SELECT num, member_num, type, category, content, status, created_date,
           ROW_NUMBER() OVER(ORDER BY num DESC) AS row_num
    FROM report
    WHERE member_num = #{member_num}
) numbered_rows
WHERE row_num BETWEEN #{begin} AND #{end}

SELECT COUNT(*)
FROM report
WHERE member_num = #{member_num}

SELECT num, member_num, type, category, content, status, created_date, row_num
FROM (
    SELECT num, member_num, type, category, content, status, created_date,
           ROW_NUMBER() OVER(ORDER BY num DESC) AS row_num
    FROM report





                    type LIKE '%' || #{searchValue} || '%'



                    category LIKE '%' || #{searchValue} || '%'



                    status = #{searchValue}




) numbered_rows
WHERE row_num BETWEEN #{begin} AND #{end}

SELECT num, member_num, type, category, content, status, created_date
FROM report
WHERE num = #{num}

mapper.update:
UPDATE report
SET type = #{type},
    category = #{category},
    content = #{content}
WHERE num = #{num}

UPDATE report
SET status = #{status}
WHERE num = #{num}
